def urlnorm3986(url):
    if not isinstance(url, str):
        raise ValueError("URL must be a string")
    if not all(0x21 <= ord(c) <= 0x7E for c in url):
        raise ValueError("URL contains invalid characters")

    # Split scheme
    colon = url.find(':')
    if colon == -1:
        raise ValueError("Missing scheme")
    scheme = url[:colon]
    if not scheme or not scheme[0].isalpha():
        raise ValueError("Scheme must start with a letter")
    if not all(c.isalnum() or c in '+-.' for c in scheme):
        raise ValueError("Invalid scheme characters")
    if not url.startswith(scheme + '://'):
        raise ValueError("Missing ://")
    scheme = scheme.lower()
    rest = url[len(scheme) + 3:]

    # Split authority, path, query, fragment
    # Authority runs to the first /, ?, or #
    auth_end = len(rest)
    for i, c in enumerate(rest):
        if c in '/?#':
            auth_end = i
            break
    authority = rest[:auth_end]
    remaining = rest[auth_end:]

    # Path runs to the first ? or #
    path_end = len(remaining)
    for i, c in enumerate(remaining):
        if c in '?#':
            path_end = i
            break
    path = remaining[:path_end]
    remaining = remaining[path_end:]

    # Query
    query = ''
    query_present = False
    if remaining.startswith('?'):
        query_present = True
        hash_idx = remaining.find('#')
        if hash_idx != -1:
            query = remaining[1:hash_idx]
            remaining = remaining[hash_idx:]
        else:
            query = remaining[1:]
            remaining = ''

    # Fragment
    fragment = ''
    fragment_present = False
    if remaining.startswith('#'):
        fragment_present = True
        fragment = remaining[1:]
        remaining = ''

    # Percent normalization helper
    def norm_pct(s):
        res = []
        i = 0
        while i < len(s):
            if s[i] == '%':
                if i + 2 >= len(s) or not (s[i+1] in '0123456789ABCDEFabcdef' and s[i+2] in '0123456789ABCDEFabcdef'):
                    raise ValueError("Invalid percent encoding")
                h = int(s[i+1:i+3], 16)
                c = chr(h)
                if c in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._~':
                    res.append(c)
                else:
                    res.append('%')
                    res.append(s[i+1].upper())
                    res.append(s[i+2].upper())
                i += 3
            else:
                res.append(s[i])
                i += 1
        return ''.join(res)

    # Helper to lowercase host while preserving encoded triplets
    def lower_host(s):
        res = []
        i = 0
        while i < len(s):
            if s[i] == '%' and i + 2 < len(s) and s[i+1] in '0123456789ABCDEFabcdef' and s[i+2] in '0123456789ABCDEFabcdef':
                # Keep triplet as is (already normalized to uppercase hex)
                res.append('%')
                res.append(s[i+1].upper())
                res.append(s[i+2].upper())
                i += 3
            else:
                res.append(s[i].lower())
                i += 1
        return ''.join(res)

    unreserved = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._~')
    subdelims = set("!$&'()*+,;=")

    # Authority parsing
    if authority.count('@') > 1:
        raise ValueError("Multiple @ in authority")
    userinfo = None
    if '@' in authority:
        at = authority.index('@')
        userinfo = authority[:at]
        host_port = authority[at+1:]
    else:
        host_port = authority

    if userinfo == '':
        userinfo = None

    if userinfo is not None:
        userinfo = norm_pct(userinfo)
        allowed_u = unreserved | subdelims | set(':')
        for c in userinfo:
            if c == '%':
                continue
            if c not in allowed_u:
                raise ValueError("Invalid userinfo characters")

    # Split host and port from host_port
    port_str = ''
    if host_port.startswith('['):
        bracket = host_port.find(']')
        if bracket == -1:
            raise ValueError("Missing ] in host")
        host_raw = host_port[:bracket+1]
        after = host_port[bracket+1:]
        if after and after[0] == ':':
            port_str = after[1:]
        elif after:
            raise ValueError("Invalid characters after IPv6 host")
        else:
            port_str = ''
    else:
        colon = host_port.rfind(':')
        if colon != -1:
            host_raw = host_port[:colon]
            port_str = host_port[colon+1:]
        else:
            host_raw = host_port
            port_str = ''

    # Validate and normalize host
    if host_raw.startswith('['):
        if not host_raw[1:-1]:
            raise ValueError("Empty IPv6 host")
        for c in host_raw[1:-1]:
            if c not in '0123456789ABCDEFabcdef:.':
                raise ValueError("Invalid IPv6 host characters")
        host = '[' + host_raw[1:-1].lower() + ']'
    else:
        if not host_raw:
            raise ValueError("Empty host")
        host = norm_pct(host_raw)
        allowed_h = unreserved | subdelims
        for c in host:
            if c == '%':
                continue
            if c not in allowed_h:
                raise ValueError("Invalid host characters")
        host = lower_host(host)

    # Validate port
    if port_str:
        if not port_str.isdigit():
            raise ValueError("Port must contain only digits")
        port_val = int(port_str)
        if port_val > 65535:
            raise ValueError("Port value exceeds 65535")
        default_ports = {'http': 80, 'https': 443, 'ftp': 21, 'ws': 80, 'wss': 443}
        if port_val != default_ports.get(scheme):
            port_str = str(port_val)
        else:
            port_str = ''
    else:
        port_str = ''

    auth_str = ''
    if userinfo is not None:
        auth_str += userinfo + '@'
    auth_str += host
    if port_str:
        auth_str += ':' + port_str

    # Path normalization
    if not path:
        path = '/'
    else:
        path = norm_pct(path)
        allowed_p = unreserved | subdelims | set(':@/')
        for c in path:
            if c == '%':
                continue
            if c not in allowed_p:
                raise ValueError("Invalid path characters")

        # Dot segment removal
        input_buf = path
        output_buf = []
        while input_buf:
            if input_buf.startswith('../') or input_buf.startswith('./'):
                input_buf = input_buf[3:] if input_buf.startswith('../') else input_buf[2:]
            elif input_buf.startswith('/./') or input_buf == '/.':
                input_buf = '/' + input_buf[3:] if input_buf.startswith('/./') else '/'
            elif input_buf.startswith('/../') or input_buf == '/..':
                input_buf = '/' + input_buf[4:] if input_buf.startswith('/../') else '/'
                if output_buf:
                    output_buf.pop()
            elif input_buf in ('.', '..'):
                input_buf = ''
            else:
                if input_buf.startswith('/'):
                    slash_idx = input_buf.find('/', 1)
                    if slash_idx == -1:
                        segment = input_buf
                        input_buf = ''
                    else:
                        segment = input_buf[:slash_idx]
                        input_buf = input_buf[slash_idx:]
                else:
                    slash_idx = input_buf.find('/')
                    if slash_idx == -1:
                        segment = input_buf
                        input_buf = ''
                    else:
                        segment = input_buf[:slash_idx]
                        input_buf = input_buf[slash_idx:]
                output_buf.append(segment)

        path = ''.join(output_buf)
        if not path:
            path = '/'

    # Query normalization
    query = norm_pct(query)
    allowed_q = unreserved | subdelims | set(':@/?')
    for c in query:
        if c == '%':
            continue
        if c not in allowed_q:
            raise ValueError("Invalid query characters")

    # Fragment normalization
    fragment = norm_pct(fragment)
    allowed_f = unreserved | subdelims | set(':@/?')
    for c in fragment:
        if c == '%':
            continue
        if c not in allowed_f:
            raise ValueError("Invalid fragment characters")

    return scheme + '://' + auth_str + path + ('?' + query if query_present else '') + ('#' + fragment if fragment_present else '')

from fractions import Fraction

def simplest_between(lo, hi, lo_incl=True, hi_incl=True):
    """
    Returns the simplest fraction in the interval [lo, hi] (or open/closed as specified).
    Simplest means smallest denominator, then smallest absolute numerator.
    """
    # Type checks
    if type(lo_incl) is not bool or type(hi_incl) is not bool:
        raise ValueError("lo_incl and hi_incl must be bool")
    if type(lo) is bool or type(hi) is bool:
        raise ValueError("lo and hi must not be bool")
    if not isinstance(lo, (int, Fraction)) or not isinstance(hi, (int, Fraction)):
        raise ValueError("lo and hi must be int or Fraction")

    lo = Fraction(lo)
    hi = Fraction(hi)

    if lo > hi:
        raise ValueError("lo must be <= hi")
    if lo == hi and not (lo_incl and hi_incl):
        raise ValueError("Interval is empty")

    # Check if 0 is in the interval
    zero_in = (lo < 0 < hi) or (lo == 0 and lo_incl) or (hi == 0 and hi_incl)
    if zero_in:
        return Fraction(0)

    # Handle negative interval by symmetry
    if lo < 0 and hi < 0:
        lo, hi = -hi, -lo
        lo_incl, hi_incl = hi_incl, lo_incl
        res = _simplest_positive(lo, hi, lo_incl, hi_incl)
        return Fraction(-res.numerator, res.denominator)
    else:
        # 0 < lo < hi
        return _simplest_positive(lo, hi, lo_incl, hi_incl)

def _simplest_positive(lo, hi, lo_incl, hi_incl):
    """
    Finds the simplest fraction in (0, inf) within [lo, hi].
    Uses a modified Stern-Brocot search with integer arithmetic.
    """
    # Initial bounds for Stern-Brocot tree: 0/1 and 1/0 (infinity)
    l_num, l_den = 0, 1
    r_num, r_den = 1, 0

    while True:
        # Mediant
        m_num = l_num + r_num
        m_den = l_den + r_den

        # Compare m with lo and hi using cross-multiplication
        cmp_lo = m_num * lo.denominator - lo.numerator * m_den
        cmp_hi = m_num * hi.denominator - hi.numerator * m_den

        if cmp_lo < 0:
            # m < lo. m is too small.
            l_num, l_den = m_num, m_den
        elif cmp_hi > 0:
            # m > hi. m is too large.
            r_num, r_den = m_num, m_den
        else:
            # lo <= m <= hi
            # Check inclusion constraints
            if cmp_lo == 0 and not lo_incl:
                l_num, l_den = m_num, m_den
            elif cmp_hi == 0 and not hi_incl:
                r_num, r_den = m_num, m_den
            else:
                return Fraction(m_num, m_den)

def rank_mini_league(results):
    # Input validation
    if not isinstance(results, list):
        raise ValueError("Input must be a list")

    matches = []
    teams = set()

    for match in results:
        if not isinstance(match, (list, tuple)) or len(match) != 4:
            raise ValueError("Each match must be a tuple/list of 4 elements")

        h, a, hg, ag = match

        if not isinstance(h, str) or len(h) == 0:
            raise ValueError("Home team must be a non-empty string")
        if not isinstance(a, str) or len(a) == 0:
            raise ValueError("Away team must be a non-empty string")
        if h == a:
            raise ValueError("Home and away teams must be different")

        # Check for bool explicitly because bool is a subclass of int
        # type(x) is int ensures x is exactly an int, not a bool or other subclass
        if type(hg) is not int or type(ag) is not int:
            raise ValueError("Goals must be integers")

        if not (0 <= hg <= 99):
            raise ValueError("Goals must be between 0 and 99")
        if not (0 <= ag <= 99):
            raise ValueError("Goals must be between 0 and 99")

        matches.append((h, a, hg, ag))
        teams.add(h)
        teams.add(a)

    if not teams:
        return []

    # Compute Global Stats
    global_points = {t: 0 for t in teams}
    global_gs = {t: 0 for t in teams}
    global_gc = {t: 0 for t in teams}

    for h, a, hg, ag in matches:
        global_gs[h] += hg
        global_gc[h] += ag
        global_gs[a] += ag
        global_gc[a] += hg

        if hg > ag:
            global_points[h] += 3
        elif hg == ag:
            global_points[h] += 1
            global_points[a] += 1
        else:
            global_points[a] += 3

    # Group teams by Total Points
    points_groups = {}
    for t in teams:
        p = global_points[t]
        if p not in points_groups:
            points_groups[p] = []
        points_groups[p].append(t)

    # Sort groups by points descending
    sorted_points = sorted(points_groups.keys(), reverse=True)

    final_order = []

    for p in sorted_points:
        group_teams = points_groups[p]

        # Filter matches for this group (matches where both teams are in the group)
        group_matches = [m for m in matches if m[0] in group_teams and m[1] in group_teams]

        # Compute Mini Stats
        mini_pts = {t: 0 for t in group_teams}
        mini_gs = {t: 0 for t in group_teams}
        mini_gc = {t: 0 for t in group_teams}
        mini_awg = {t: 0 for t in group_teams}

        for h, a, hg, ag in group_matches:
            if hg > ag:
                mini_pts[h] += 3
            elif hg == ag:
                mini_pts[h] += 1
                mini_pts[a] += 1
            else:
                mini_pts[a] += 3

            mini_gs[h] += hg
            mini_gc[h] += ag
            mini_gs[a] += ag
            mini_gc[a] += hg

            # Away goals are scored by the away team (a)
            mini_awg[a] += ag

        mini_gd = {t: mini_gs[t] - mini_gc[t] for t in group_teams}

        # Sort teams within the group
        # Criteria:
        # 1. Mini points (higher first) -> -mini_pts
        # 2. Mini goal difference (higher first) -> -mini_gd
        # 3. Mini goals scored (higher first) -> -mini_gs
        # 4. Mini away goals (higher first) -> -mini_awg
        # 5. Overall goal difference (higher first) -> -global_gd
        # 6. Overall goals scored (higher first) -> -global_gs
        # 7. Team name (ascending code point) -> t

        def sort_key(t):
            ogd = global_gs[t] - global_gc[t]
            ogs = global_gs[t]
            return (
                -mini_pts[t],
                -mini_gd[t],
                -mini_gs[t],
                -mini_awg[t],
                -ogd,
                -ogs,
                t
            )

        sorted_group = sorted(group_teams, key=sort_key)
        final_order.extend(sorted_group)

    return final_order

