def replay_editor_log(commands):
    if not isinstance(commands, list):
        raise ValueError
    if len(commands) > 2000:
        raise ValueError

    text = ""
    cursor = 0
    undo_stack = []
    redo_stack = []
    current_group = None
    # current_group is a dict with keys: 'tb' (text before), 'cb' (cursor before), 
    # 'ta' (text after), 'ca' (cursor after).
    # It represents a group of commands that have been executed but not yet committed to undo_stack.
    # A group is "committed" when a command comes that does not extend it.
    # A "type" command extends a group only if the current group is also a "type" run.
    # We track this with a flag or by checking the nature of the group.
    # Actually, simpler: 'type' extends only if current_group exists AND was created by 'type'.
    # 'back'/'del' creates a group that cannot be extended.
    # Other commands commit current_group and do not create one.

    # To track if current_group is a type run, we can store a flag or just check logic.
    # Let's store a flag 'is_type_run' in the group dict.

    for cmd in commands:
        if not isinstance(cmd, (tuple, list)):
            raise ValueError
        if len(cmd) > 2:
            raise ValueError
        name = cmd[0]

        # Validate arguments
        if name == "type":
            if len(cmd) != 2 or not isinstance(cmd[1], str) or not (1 <= len(cmd[1]) <= 20):
                raise ValueError
        elif name in ("back", "del", "left", "right"):
            if len(cmd) != 2:
                raise ValueError
            n = cmd[1]
            if isinstance(n, bool) or not isinstance(n, int):
                raise ValueError
            if not (1 <= n <= 10**6):
                raise ValueError
        elif name in ("home", "end", "undo", "redo"):
            if len(cmd) != 1:
                raise ValueError
        else:
            raise ValueError

        # Determine if this command extends the current group.
        # Only "type" extends an existing group, and only if that group was a type run.
        extends_current = False
        if name == "type":
            if current_group is not None and current_group.get('is_type_run', False):
                extends_current = True

        # If we have a pending group and this command does not extend it,
        # we must commit the pending group to the undo stack.
        if current_group is not None and not extends_current:
            undo_stack.append(current_group)
            current_group = None

        old_text = text
        old_cursor = cursor

        if name == "type":
            s = cmd[1]
            text = text[:cursor] + s + text[cursor:]
            cursor += len(s)
            if current_group is None:
                # Start a new type group
                current_group = {'tb': old_text, 'cb': old_cursor, 'ta': text, 'ca': cursor, 'is_type_run': True}
            else:
                # Extend existing type group
                current_group['ta'] = text
                current_group['ca'] = cursor
            redo_stack.clear()

        elif name == "back":
            n = cmd[1]
            del_count = min(n, cursor)
            text = text[:cursor - del_count] + text[cursor:]
            cursor -= del_count
            if del_count > 0:
                # Start a new delete group (cannot be extended)
                current_group = {'tb': old_text, 'cb': old_cursor, 'ta': text, 'ca': cursor, 'is_type_run': False}
                redo_stack.clear()

        elif name == "del":
            n = cmd[1]
            del_count = min(n, len(text) - cursor)
            text = text[:cursor] + text[cursor + del_count:]
            if del_count > 0:
                # Start a new delete group (cannot be extended)
                current_group = {'tb': old_text, 'cb': old_cursor, 'ta': text, 'ca': cursor, 'is_type_run': False}
                redo_stack.clear()

        elif name == "left":
            n = cmd[1]
            cursor = max(0, cursor - n)
        elif name == "right":
            n = cmd[1]
            cursor = min(len(text), cursor + n)
        elif name == "home":
            cursor = 0
        elif name == "end":
            cursor = len(text)
        elif name == "undo":
            # Undo takes the most recent group off the undo stack.
            # Note: current_group is already committed if it didn't extend, 
            # so it's in undo_stack.
            group_to_undo = None
            if undo_stack:
                group_to_undo = undo_stack.pop()

            if group_to_undo is not None:
                text = group_to_undo['tb']
                cursor = group_to_undo['cb']
                redo_stack.append(group_to_undo)

        elif name == "redo":
            if redo_stack:
                group_to_redo = redo_stack.pop()
                text = group_to_redo['ta']
                cursor = group_to_redo['ca']
                undo_stack.append(group_to_redo)

    # Commit any remaining pending group
    if current_group is not None:
        undo_stack.append(current_group)

    return text, cursor, len(undo_stack), len(redo_stack)

