        # Only "type" extends, and only if current_group is a type run
        extends = False
        if name == "type":
            if current_group is not None and current_group.get('is_type_run', False):
                extends = True

        # If current group exists and is not extended, commit it
        if current_group is not None and not extends:
            undo_stack.append(current_group)
            current_group = None

        # --- Execute Command ---
        old_text = text
        old_cursor = cursor

        if name == "type":
            s = cmd[1]
            text = text[:cursor] + s + text[cursor:]
            cursor += len(s)

            if extends:
                # Update existing group
                current_group['ta'] = text
                current_group['ca'] = cursor
            else:
                # Start new group
                current_group = {
                    'tb': old_text,
                    'cb': old_cursor,
                    'ta': text,
                    'ca': cursor,
                    'is_type_run': True
                }
            redo_stack.clear()

        elif name == "back":
            n = cmd[1]
            del_count = min(n, cursor)
            text = text[:cursor - del_count] + text[cursor:]
            cursor -= del_count

            if del_count > 0:
                # Start new delete group
                current_group = {
                    'tb': old_text,
                    'cb': old_cursor,
                    'ta': text,
                    'ca': cursor,
                    'is_type_run': False
                }
                redo_stack.clear()
            # else: no group created, redo_stack untouched

        elif name == "del":
            n = cmd[1]
            del_count = min(n, len(text) - cursor)
            text = text[:cursor] + text[cursor + del_count:]
            # cursor stays same

            if del_count > 0:
                current_group = {
                    'tb': old_text,
                    'cb': old_cursor,
                    'ta': text,
                    'ca': cursor,
                    'is_type_run': False
                }
                redo_stack.clear()

        elif name == "left":
            n = cmd[1]
            cursor = max(0, cursor - n)

        elif name == "right":
            n = cmd[1]
            cursor = min(len(text), cursor + n)

        elif name == "home":
            cursor = 0

        elif name == "end":
            cursor = len(text)

        elif name == "undo":
            if undo_stack:
                g = undo_stack.pop()
                text = g['tb']
                cursor = g['cb']
                redo_stack.append(g)
            # Undo does not create/extend group, so no redo clear.

        elif name == "redo":
            if redo_stack:
                g = redo_stack.pop()
                text = g['ta']
                cursor = g['ca']
                undo_stack.append(g)
            # Redo does not create/extend group, so no redo clear.

    # Commit any remaining pending group
    if current_group is not None:
        undo_stack.append(current_group)

    return text, cursor, len(undo_stack), len(redo_stack)
